let slots = DispatchSemaphore(value: 8)

func handle(_ request: Request) {
    if slots.wait(timeout: .now() + .milliseconds(250)) == .timedOut {
        return reject(request)
    }
    defer { slots.signal() }          // released on every exit path
    serve(request)
}

